from pathlib import Path

p = Path('index.html')
s = p.read_text(encoding='utf-8')

def rep(old, new, label):
    global s
    count = s.count(old)
    if count != 1:
        raise SystemExit(f'{label}: marker count={count}')
    s = s.replace(old, new, 1)

rep(
    ".purchase-metrics{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:12px}.purchase-metrics .card{padding:12px}.purchase-metrics .num{font-size:18px}.purchase-card.to-me{border-left:4px solid #7c3aed}",
    ".purchase-metrics{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:12px}.purchase-metrics .card{padding:12px}.purchase-metrics .num{font-size:18px}.purchase-card{cursor:pointer}.purchase-card.to-me{border-left:4px solid #7c3aed}",
    'purchase card clickable css',
)

rep(
    '''<section id="purchases" class="view"><h2>Закупки</h2><div class="purchase-metrics"><div class="card"><div class="label">К доставщику</div><div class="num" id="pToForwarder">0 шт.</div></div><div class="card"><div class="label">Едет ко мне</div><div class="num" id="pToMe">0 шт.</div></div><div class="card"><div class="label">В пути, вложено</div><div class="num" id="pInTransitValue">0 ₸</div></div><div class="card"><div class="label">Получено за 30 дней</div><div class="num" id="pReceived30">0 шт.</div></div></div><button class="btn dark full" onclick="openModal('purchase')">+ Новая закупка</button><button class="btn full" onclick="openModal('arrival')">Приход сразу на склад</button><div id="purchaseList" class="list" style="margin-top:10px"></div></section>''',
    '''<section id="purchases" class="view"><h2>Закупки</h2><div class="purchase-metrics"><div class="card"><div class="label">К доставщику</div><div class="num" id="pToForwarder">0 шт.</div></div><div class="card"><div class="label">Едет ко мне</div><div class="num" id="pToMe">0 шт.</div></div><div class="card"><div class="label">В пути, вложено</div><div class="num" id="pInTransitValue">0 ₸</div></div><div class="card"><div class="label">Получено за 30 дней</div><div class="num" id="pReceived30">0 шт.</div></div></div><button class="btn dark full" onclick="openModal('purchase')">+ Новая закупка</button><button class="btn full" onclick="openModal('arrival')">Приход сразу на склад</button><div class="purchase-search-wrap" style="margin-top:10px"><input id="purchaseSearch" autocomplete="off" placeholder="Поиск поставки по трек-коду" oninput="renderPurchases()"><div class="purchase-search-hint">Поиск по названию поставки / трек-коду</div></div><div id="purchaseList" class="list"></div></section>''',
    'purchase search input',
)

old_render = '''function renderPurchases(){const groups=purchaseShipmentGroups(),toForwarder=groups.filter(g=>g.status==='to_forwarder'),toMe=groups.filter(g=>g.status==='to_me'),received=groups.filter(g=>g.status==='received'),sumQty=a=>a.reduce((n,g)=>n+purchaseShipmentTotals(g).qty,0),inTransit=[...toForwarder,...toMe],inTransitValue=inTransit.reduce((n,g)=>{const t=purchaseShipmentTotals(g);return n+t.buy+t.delivery},0),since=reportPeriodStart(30),received30=received.filter(g=>Number(g.receivedAt)>=since);const set=(id,v)=>{const e=document.getElementById(id);if(e)e.textContent=v};set('pToForwarder',sumQty(toForwarder).toLocaleString('ru-RU')+' шт.');set('pToMe',sumQty(toMe).toLocaleString('ru-RU')+' шт.');set('pInTransitValue',fmt(inTransitValue));set('pReceived30',sumQty(received30).toLocaleString('ru-RU')+' шт.');const list=document.getElementById('purchaseList');if(!list)return;if(!groups.length){list.innerHTML='<div class="empty">Закупок пока нет</div>';return}list.innerHTML=groups.map(g=>{const t=purchaseShipmentTotals(g),status=g.status,label=status==='to_forwarder'?'К доставщику':status==='to_me'?'Едет ко мне':'Получено',badge=status==='to_me'?'purple':status==='received'?'':'',date=status==='received'?g.receivedAt:status==='to_me'?g.forwarderReceivedAt:g.orderedAt,dateLabel=status==='received'?'Получено':status==='to_me'?'У доставщика с':'Заказано',lines=g.rows.map(x=>{const qty=Number(x.qty)||0,buy=Number(x.buyTotal)||((Number(x.unitCost)||0)*qty),unitBuy=qty?buy/qty:0;return `<div class="purchase-line"><div class="grow"><b>${esc(prod(x.productId)?.name||'—')}</b><div class="muted">${qty} шт. · закуп ${fmt(unitBuy)}/шт.</div></div>${status==='received'?`<div class="right"><div class="muted">себестоимость</div><b>${fmt(x.landedUnitCost)}/шт.</b></div>`:''}</div>`}).join(''),action=status==='to_forwarder'?`<button class="btn dark full" onclick="advancePurchaseShipment('${encodeURIComponent(g.key)}')">Доставщик получил</button>`:status==='to_me'?`<button class="btn dark full" onclick="openReceivePurchaseShipment('${encodeURIComponent(g.key)}')">Получить поставку</button>`:'';return `<div class="item purchase-card ${status==='to_me'?'to-me':status==='received'?'received':'to-forwarder'}"><div class="order-head"><div class="grow"><div class="name">${esc(g.batch||'Поставка')}</div><div class="muted">${dateLabel}: ${date?new Date(date).toLocaleDateString('ru-RU'):'—'} · ${g.rows.length} поз. · ${t.qty} шт.</div></div><span class="badge ${badge}">${label}</span></div><div class="muted" style="margin-top:7px">Закупка: ${fmt(t.buy)} · доставка: ${fmt(t.delivery)} · всего: ${fmt(t.buy+t.delivery)}</div><div class="purchase-lines">${lines}</div>${status!=='received'?`<button class="btn full" onclick="openEditPurchaseShipment('${encodeURIComponent(g.key)}')">Редактировать поставку</button>`:''}${action}</div>`}).join('')}'''

new_render = '''function renderPurchases(){const allGroups=purchaseShipmentGroups(),q=normalizeName(document.getElementById('purchaseSearch')?.value||''),groups=q?allGroups.filter(g=>normalizeName([g.batch,g.key].filter(Boolean).join(' ')).includes(q)):allGroups,toForwarder=allGroups.filter(g=>g.status==='to_forwarder'),toMe=allGroups.filter(g=>g.status==='to_me'),received=allGroups.filter(g=>g.status==='received'),sumQty=a=>a.reduce((n,g)=>n+purchaseShipmentTotals(g).qty,0),inTransit=[...toForwarder,...toMe],inTransitValue=inTransit.reduce((n,g)=>{const t=purchaseShipmentTotals(g);return n+t.buy+t.delivery},0),since=reportPeriodStart(30),received30=received.filter(g=>Number(g.receivedAt)>=since);const set=(id,v)=>{const e=document.getElementById(id);if(e)e.textContent=v};set('pToForwarder',sumQty(toForwarder).toLocaleString('ru-RU')+' шт.');set('pToMe',sumQty(toMe).toLocaleString('ru-RU')+' шт.');set('pInTransitValue',fmt(inTransitValue));set('pReceived30',sumQty(received30).toLocaleString('ru-RU')+' шт.');const list=document.getElementById('purchaseList');if(!list)return;if(!allGroups.length){list.innerHTML='<div class="empty">Закупок пока нет</div>';return}if(!groups.length){list.innerHTML='<div class="empty">Поставки по этому трек-коду не найдены</div>';return}list.innerHTML=groups.map(g=>{const t=purchaseShipmentTotals(g),status=g.status,label=status==='to_forwarder'?'К доставщику':status==='to_me'?'Едет ко мне':'Получено',badge=status==='to_me'?'purple':status==='received'?'':'',date=status==='received'?g.receivedAt:status==='to_me'?g.forwarderReceivedAt:g.orderedAt,dateLabel=status==='received'?'Получено':status==='to_me'?'У доставщика с':'Заказано',lines=g.rows.map(x=>{const qty=Number(x.qty)||0,buy=Number(x.buyTotal)||((Number(x.unitCost)||0)*qty),unitBuy=qty?buy/qty:0;return `<div class="purchase-line"><div class="grow"><b>${esc(prod(x.productId)?.name||'—')}</b><div class="muted">${qty} шт. · закуп ${fmt(unitBuy)}/шт.</div></div>${status==='received'?`<div class="right"><div class="muted">себестоимость</div><b>${fmt(x.landedUnitCost)}/шт.</b></div>`:''}</div>`}).join(''),key=encodeURIComponent(g.key);return `<div class="item purchase-card ${status==='to_me'?'to-me':status==='received'?'received':'to-forwarder'}" role="button" tabindex="0" onclick="openPurchaseShipment('${key}')" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();openPurchaseShipment('${key}')}"><div class="order-head"><div class="grow"><div class="name">${esc(g.batch||'Поставка')}</div><div class="muted">${dateLabel}: ${date?new Date(date).toLocaleDateString('ru-RU'):'—'} · ${g.rows.length} поз. · ${t.qty} шт.</div></div><span class="badge ${badge}">${label}</span></div><div class="muted" style="margin-top:7px">Закупка: ${fmt(t.buy)} · доставка: ${fmt(t.delivery)} · всего: ${fmt(t.buy+t.delivery)}</div><div class="purchase-lines">${lines}</div></div>`}).join('')}'''
rep(old_render, new_render, 'purchase list cards and search')

marker = '''function purchaseShipmentRows(encodedKey){const key=decodeURIComponent(String(encodedKey||''));return (state.purchases||[]).filter(x=>String(x.shipmentId||x.id||'')===key)}\nfunction openEditPurchaseShipment(encodedKey)'''
insert = r'''function purchaseShipmentRows(encodedKey){const key=decodeURIComponent(String(encodedKey||''));return (state.purchases||[]).filter(x=>String(x.shipmentId||x.id||'')===key)}
function openPurchaseShipment(encodedKey){const rows=purchaseShipmentRows(encodedKey);if(!rows.length)return alert('Поставка не найдена');const first=rows[0],status=purchaseStatus(first),t=purchaseShipmentTotals({rows}),key=encodeURIComponent(String(first.shipmentId||first.id||'')),label=status==='to_forwarder'?'К доставщику':status==='to_me'?'Едет ко мне':'Получено',badge=status==='to_me'?'purple':status==='received'?'':'',date=status==='received'?rows.reduce((a,x)=>Math.max(a,Number(x.receivedAt)||0),0):status==='to_me'?rows.reduce((a,x)=>Math.max(a,Number(x.forwarderReceivedAt)||0),0):Number(first.orderedAt||first.date)||0,dateLabel=status==='received'?'Получено':status==='to_me'?'У доставщика с':'Заказано',lines=rows.map(x=>{const qty=Number(x.qty)||0,buy=Number(x.buyTotal)||((Number(x.unitCost)||0)*qty),unitBuy=qty?buy/qty:0;return `<div class="purchase-line"><div class="grow"><b>${esc(prod(x.productId)?.name||'—')}</b><div class="muted">${qty} шт. · закуп ${fmt(unitBuy)}/шт.</div></div>${status==='received'?`<div class="right"><div class="muted">себестоимость</div><b>${fmt(x.landedUnitCost)}/шт.</b></div>`:''}</div>`}).join(''),edit=status!=='received'?`<button class="btn full" onclick="openEditPurchaseShipment('${key}')">Редактировать поставку</button>`:'<div class="link-note">Поставка уже оприходована: остаток и FIFO зафиксированы. Её можно просматривать, но изменение количества после получения отключено.</div>',action=status==='to_forwarder'?`<button class="btn dark full" onclick="advancePurchaseShipment('${key}')">Доставщик получил</button>`:status==='to_me'?`<button class="btn dark full" onclick="openReceivePurchaseShipment('${key}')">Получить поставку</button>`:'';showSheet(`<h3>${esc(first.batch||'Поставка')}</h3><div class="item"><div class="order-head"><div class="grow"><div class="muted">${dateLabel}: ${date?new Date(date).toLocaleDateString('ru-RU'):'—'}</div><div class="muted" style="margin-top:4px">${rows.length} поз. · ${t.qty} шт.</div></div><span class="badge ${badge}">${label}</span></div><div class="muted" style="margin-top:9px">Закупка: ${fmt(t.buy)} · доставка: ${fmt(t.delivery)} · всего: ${fmt(t.buy+t.delivery)}</div><div class="purchase-lines">${lines}</div></div>${edit}${action}`)}
function openEditPurchaseShipment(encodedKey)'''
